<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CMS · Fynefield</title><link rel="stylesheet" href="<?= base_url('assets/css/admin.css') ?>"><link rel="stylesheet" href="<?= base_url('assets/css/cms-enhancements.css') ?>"><?= $this->renderSection('head') ?></head><body><aside><a class="admin-brand" href="<?= site_url('admin') ?>">FYNEFIELD<span>CMS</span></a><nav><a href="<?= site_url('admin') ?>">Overview</a><?php foreach ($entities as $key => $item): ?><?php if (empty($item['admin_only']) || $adminRole === 'admin'): ?><a href="<?= site_url('admin/' . $key) ?>"><?= esc($item['label']) ?></a><?php endif ?><?php endforeach ?><?php if ($adminRole === 'admin'): ?><a href="<?= site_url('admin/navigation') ?>">Navigation</a><?php endif ?><a href="<?= site_url('admin/media') ?>">Media library</a><?php if ($adminRole === 'admin'): ?><a href="<?= site_url('admin/settings') ?>">Site settings</a><a href="<?= site_url('admin/users') ?>">Users</a><?php endif ?></nav><form method="post" action="<?= site_url('admin/logout') ?>"><?= csrf_field() ?><button>Sign out</button></form></aside><main><header class="admin-header"><div><p>Signed in as <a href="<?= site_url('admin/profile') ?>"><?= esc($adminName) ?></a></p></div><a href="<?= site_url('/') ?>" target="_blank" rel="noopener">View website ↗</a></header><?php if (session('success')): ?><div class="notice success"><?= esc(session('success')) ?></div><?php endif ?><?php if (session('error')): ?><div class="notice error"><?= esc(session('error')) ?></div><?php endif ?><?= $this->renderSection('content') ?></main><?= $this->renderSection('scripts') ?></body></html>
